47	        // its query's scores against keys kk*16 + 2e + hw.
48	        FRAG_B fragP[QT][KTIL];
49	#if PV_ORDER
50	        float corrq[QT], mnq[QT];
51	#endif
52	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
53	#if GUT_SOFTMAX
54	            // A3's floor: P^T is S^T narrowed, no max, exp, correction or sum.
55	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
