70	                    fragP[qq][kk][4u * i + 1u] = odd.x;
71	                    fragP[qq][kk][4u * i + 2u] = even.y;
72	                    fragP[qq][kk][4u * i + 3u] = odd.y;
73	#endif
74	                }
75	            }
76	#else
77	            float mx = -1.0 / 0.0;
78	#if GUT_MAX
79	            mx = 0.0;
80	#else
81	            if (MASKED == 0 || cnt == BN) {
82	#if MAX_TREE
83	                // A balanced tree: max is exact, so the order is free, and
