132	                [[unroll]] for (uint e = 0u; e < 8u; ++e) {
133	                    o[qq][j][e] *= corr;
134	                }
135	            }
136	#if LAZY
137	            }
138	#endif
139	#endif
140	            float sum = 0.0;
141	#if PV_ORDER
142	            corrq[qq] = corr;
143	            mnq[qq] = mn;
144	        }
145	        // The P^T tiles a key tile at a time, each one's MMAs right behind
146	        // it, so S^T dies as P^T is born and the peak register set is
147	        // smaller: o[qq][j]'s MMAs come in the same kk order as before.
148	        float sumq[QT];
149	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
150	            sumq[qq] = 0.0;
151	        }
152	        [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
153	            FRAG_B fragPk[QT];
154	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
