156	                float sum = sumq[qq];
157	#define fragP_qq_kk fragPk[qq]
158	#else
159	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
160	#define fragP_qq_kk fragP[qq][kk]
161	#endif
162	                // P^T narrowed to fp16, two keys a word: w[i] holds this
