164	                uint w[4];
165	                [[unroll]] for (uint i = 0u; i < 4u; ++i) {
166	#if GUT_EXP
167	                    float p0 = s[qq][kk][2u * i] - mn;
168	                    float p1 = s[qq][kk][2u * i + 1u] - mn;
169	#else
170	                    float p0 = exp2(s[qq][kk][2u * i] - mn);
171	                    float p1 = exp2(s[qq][kk][2u * i + 1u] - mn);
172	#endif
173	                    if (MASKED != 0 && cnt < BN) {
174	                        uint k0 = kk * TILE + 4u * i + hw;
175	                        p0 = k0 < cnt ? p0 : 0.0;
176	                        p1 = k0 + 2u < cnt ? p1 : 0.0;
177	                    }
178	                    f16vec2 h = f16vec2(p0, p1);
179	                    sum += float(h.x) + float(h.y);
180	                    w[i] = packFloat2x16(h);
181	                }
182	                // B wants keys 0..15 of this lane's query in order. The other
183	                // half-wave holds the other parity; swap and interleave.
184	                [[unroll]] for (uint i = 0u; i < 4u; ++i) {
185	                    f16vec2 mine = unpackFloat2x16(w[i]);
186	                    f16vec2 theirs = unpackFloat2x16(subgroupShuffleXor(w[i], 16u));
187	                    f16vec2 even = hw == 0u ? mine : theirs;   // keys 4i, 4i+2
188	                    f16vec2 odd = hw == 0u ? theirs : mine;    // keys 4i+1, 4i+3
189	                    fragP_qq_kk[4u * i] = even.x;
190	                    fragP_qq_kk[4u * i + 1u] = odd.x;
191	                    fragP_qq_kk[4u * i + 2u] = even.y;
192	                    fragP_qq_kk[4u * i + 3u] = odd.y;
193	                }
