205	            }
206	        }
207	        [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
208	            runSum[qq] = runSum[qq] * corrq[qq] + sumq[qq];
209	        }
210	#else
211	            }
212	            runSum[qq] = runSum[qq] * corr + sum;
213	#endif
214	#endif
215	#if !PV_ORDER || GUT_SOFTMAX
216	        }
217	
218	        // ---- O^T += V^T . P^T.
219	        [[unroll]] for (uint j = 0u; j < HDT; ++j) {
220	            FRAG_A fragV[KTIL];
221	            [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
222	                coopMatLoad(fragV[kk], hact, vBase + ((KV_BLOCK + kk) * HDT + j) * (TILE * TILE),
223	                    TILE, gl_CooperativeMatrixLayoutRowMajor);
224	            }
225	            [[unroll]] for (uint qq = 0u; qq < QT; ++qq) {
226	                [[unroll]] for (uint kk = 0u; kk < KTIL; ++kk) {
227	                    o[qq][j] = coopMatMulAdd(fragV[kk], fragP[qq][kk], o[qq][j]);
228	                }
229	            }
230	        }
231	#endif
