// AttnVariant is one build of the WMMA attention with fp16 context out: QT
// query tiles a wave, KTIL key tiles a block, wave32. T is the transposed
// kernel (h3_attn_t.comp, M11c). Tag names a build a screen loaded from a
// file (AddAttention).
type AttnVariant struct {
	QT, KTIL int
	T        bool
	Tag      string
}

// attnFor is the build for a key count. TestGPUAttentionScreen, block 49's
// planes after a real forward: the transposed QT2 KTIL4 is 1.55x the best
// plain build at 15,936 keys (194 against 297 ms) and 1.61x at 38,247 (1.17
// against 1.87 s), at rms 1e-4 of the context (M11c). It runs wherever the
// device's cooperative-matrix element order is the one it is written
// against (checkCoopMatLayout, at the first Begin). Otherwise the plain builds, whose
// screen (2026-09-26) put QT1 KTIL4 first at 15,936 keys (26.3 TFLOP/s
// against QT2's 24.5) and QT2 KTIL4 at 38,247 (22.4 against 19.6); the
// switch sits between the two measured points.
func (g *GPU) attnFor(keys int) AttnVariant {
	if g.attnFixed {
		return g.attn
	}
	if g.attnT {
		return AttnVariant{QT: 2, KTIL: 4, T: true}
	}
	if keys >= 24576 {
		return AttnVariant{QT: 2, KTIL: 4}
	}
	return AttnVariant{QT: 1, KTIL: 4}
}

// attention records one query chunk's attention of n rows over keys keys.
func (gr *graph) attention(keys, n int, pc pushConstants) {
	v := gr.g.attnFor(keys)
	rowsPer := v.QT * tile
	gr.d = append(gr.d, vk.MultiDispatch{Pipeline: gr.g.attnPipes[v], GroupsX: uint32((n + rowsPer - 1) / rowsPer),
		GroupsY: uint32(gr.g.heads), PushConstants: pc.bytes()})
	gr.kinds = append(gr.kinds, "attention")
	gr.flops = append(gr.flops, 4*float64(n)*float64(keys)*float64(gr.g.headDim)*float64(gr.g.heads))
}

var attnBuilds = map[AttnVariant][]byte{
	{QT: 1, KTIL: 4}:          shaders.DiTAttentionWMMAQT1KT4W32OutF16,
	{QT: 1, KTIL: 8}:          shaders.H3AttnQT1KT8,
	{QT: 2, KTIL: 4}:          shaders.H3AttnQT2KT4,
	{QT: 2, KTIL: 8}:          shaders.H3AttnQT2KT8,
	{QT: 4, KTIL: 4}:          shaders.H3AttnQT4KT4,
	{QT: 2, KTIL: 4, T: true}: shaders.H3AttnTQT2KT4,
}

// maxKeyBlock is the longest key block any build reads past its count.
const maxKeyBlock = 8 * tile

// AttnVariants lists the builds a screen chooses between.
func AttnVariants() []AttnVariant {
	return []AttnVariant{{QT: 1, KTIL: 4}, {QT: 1, KTIL: 8}, {QT: 2, KTIL: 4}, {QT: 2, KTIL: 8},
		{QT: 4, KTIL: 4}, {QT: 2, KTIL: 4, T: true}}
}

// AddAttention makes a candidate build of the attention available to
// SetAttention without a rebuild: a screen's arm compiled to a file. It has
// to read and write the planes as dit_attention_wmma.comp's OUT_F16 builds
// do, at v.QT query tiles a workgroup.
func (g *GPU) AddAttention(v AttnVariant, spirv []byte) error {
	if _, ok := g.attnPipes[v]; ok {
		return fmt.Errorf("dit: attention build %v exists", v)
	}
	mod, err := g.dev.NewShaderModule(spirv)
	if err != nil {
		return fmt.Errorf("dit: attention module %v: %w", v, err)
	}
	g.mods = append(g.mods, mod)
	p, err := g.dev.NewPipeline(mod, vk.PipelineSpec{Buffers: []*vk.Buffer{g.wbuf, g.abuf, g.hbuf},
		PushConstantSize: uint32(unsafe.Sizeof(pushConstants{})), RequiredSubgroupSize: 32})
	if err != nil {
		return fmt.Errorf("dit: attention pipeline %v: %w", v, err)
	}
	g.attnPipes[v] = p
	return nil
}

// SetAttention fixes the attention build every block records, overriding
// attnFor. Every build reads and writes the same planes, so a screen is one
// staging.
func (g *GPU) SetAttention(v AttnVariant) error {
	if _, ok := g.attnPipes[v]; !ok {
		return fmt.Errorf("dit: no attention build %v", v)
	}
	g.attn, g.attnFixed = v, true
	return nil
}

// TimeAttention runs the attention of one block over the planes as they
// stand (after a Step, the last block's), for every chunk of the current
// layout, and returns the device time and the context of the last chunk:
// the screen's instrument.
func (g *GPU) TimeAttention() (time.Duration, []uint16, error) {
	rows := len(g.lay.Pos)
	gr := g.newGraph()
	planeTile := uint32(g.headDim / tile * tile * tile)
	last := 0
	for r0 := 0; r0 < rows; r0 += g.chunk {
		n := min(g.chunk, rows-r0)
		pc := gr.base
		pc.Tokens = uint32(rows)
		pc.InOff = g.hQ + uint32(r0/tile)*planeTile
		pc.KOff, pc.VOff = g.hK, g.hV
		pc.OutOff, pc.LDA = g.hCtx, uint32(g.ldaInner)
		pc.Aux1 = uint32(g.planeRows)
		gr.attention(rows, n, pc)
		last = n
	}
	took, err := gr.submit()
	if err != nil {
		return 0, nil, err
	}
	return took, g.hbuf.ReadUint16At(int(g.hCtx), last*g.ldaInner), nil
}

// written with the products of zeros and ignored.

#include "dit_common.glsl"

#ifndef LDS_STAGE
#define LDS_STAGE 0
#endif
#if LDS_STAGE && STAGE_RW
// STAGE_RW (KERNELS.md G-o8): the same views without `readonly`. A
// read-only load may be reordered freely, and NIR sinks it to its use: with
// the K tiles kept as a loop (KT_LOOP) the six staging loads were sunk to
// after it, in front of the stores that consume them, with their whole
// latency exposed. Without the qualifier they stay where the source issues
// them, at the top of the slab -- provided a store to each view exists, or
// nir_opt_access infers the qualifier back (the guarded store in main()).
layout(binding = 2) buffer HAct4 { uvec4 hact4[]; };
layout(binding = 3) buffer W16x4 { uvec4 w16x4[]; };
#elif LDS_STAGE
// The staging copies read A and B 16 bytes a lane; under LDS_STAGE these are
// the only reads of either arena, so the bindings are declared as uvec4.
layout(binding = 2) readonly buffer HAct4 { uvec4 hact4[]; };
layout(binding = 3) readonly buffer W16x4 { uvec4 w16x4[]; };
#else
layout(binding = 2) buffer HAct { float16_t hact[]; };
layout(binding = 3) readonly buffer W16 { float16_t w16[]; };
#endif
#if LDS_STAGE && (C_F16 || C_PACK || C_SWIGLU)
// The fp16 epilogues store halves into the same arena the staging reads as
// uvec4: a second view of binding 2 (KERNELS.md G3).
layout(binding = 2) buffer HAct { float16_t hact[]; };
#endif

#ifndef WM
#define WM 4        // accumulator tiles per wave, M direction
#endif
#ifndef WN
#define WN 4        // accumulator tiles per wave, N direction
#endif
#ifndef WAVES_M
#define WAVES_M 1   // waves per workgroup, M direction

